"""Explicit PCM physics problems with assumptions and misconception distractors."""
from .core import add,Q,F,fmt

c='physics-1-01'
add(c,'uncertainty-product',lambda n:Q(f'V=πr²h। r-এর maximum relative error {n}%, h-এর 2%। V-এর first-order maximum error কত %?',2*n+2,[n+2,n*n+2,2*n],'Product-এর maximum relative errors যোগ হয়, powers multiplier: ΔV/V≈2Δr/r+Δh/h=(2n+2)%।'))
add(c,'instrument-zero',lambda n:Q(f'Vernier reading {n}.20 mm, positive zero error 0.05 mm। corrected reading কত mm?',f'{n}.15',[f'{n}.25',f'{n}.20',f'{n}.05'],'Correct reading=observed−zero error। positive zero error থাকলে বেশি পড়ে; 0.05 mm বাদ দিতে হয়।'))
add(c,'dimension-constraint',lambda n:Q(f'F=kv^{n}, যেখানে F বল ও v বেগ। k-এর dimension কোনটি?',f'M L^{1-n} T^{n-2}',[f'M L^{n-1} T^{2-n}',f'M L^{1-n} T^{2-n}',f'M L^{n} T^{n}'],'[k]=[F]/[v]ⁿ=(MLT⁻²)/(LT⁻¹)ⁿ=M L^(1−n) T^(n−2)।'))
add(c,'significant-subtraction',lambda n:Q(f'{n}.25 cm−1.2 cm-এর experimental result যথাযথ decimal place-এ কত cm?',f'{n-1}.1',[f'{n-1}.05',f'{n-1}.050',str(n-1)],'Subtraction-এ least precise decimal place রাখতে হয়। raw result (n−1).05; one decimal-এ (n−1).1।'))
add(c,'least-count-derived',lambda n:Q(f'20 vernier divisions=19 main scale divisions। 1 MSD={n}/10 mm। least count কত mm?',F(n,200),[F(n,20),F(n,10),F(19*n,200)],'1 VSD=(19/20)MSD। least count=MSD−VSD=MSD/20=n/200 mm।'))
add(c,'error-in-difference',lambda n:Q(f'A=({n+5}±0.2) cm, B=({n}±0.1) cm। A−B-এর maximum absolute uncertainty কত cm?',F(3,10),[F(1,10),F(1,5),F(1,100)],'Difference-এ worst-case absolute uncertainties যোগ: Δ(A−B)≤ΔA+ΔB=0.3 cm; measured values cancel।'))
add(c,'density-error',lambda n:Q(f'ρ=m/L³। mass-এর uncertainty 2%, length-এর {n}%। density-এর first-order maximum relative uncertainty কত %?',2+3*n,[2+n,2-3*n,6*n],'Quotient হলেও maximum uncertainty magnitudes যোগ। power 3 থেকে 3ΔL/L; total 2+3n percent।'))
add(c,'graph-unit',lambda n:Q(f'Force বনাম extension graph-এর slope {n} N/cm। SI spring constant কত N/m?',100*n,[F(n,100),n,10*n],'Hooke law F=kx; slope k। 1 N/cm=100 N/m, কারণ 1 cm=0.01 m।'))
add(c,'dimension-energy-over-time',lambda n:Q(f'এক quantity Q=energy^{n}/time। dimension কোনটি?',f'M^{n} L^{2*n} T^{-(2*n+1)}',[f'M^{n} L^{n} T^{-n}',f'M^{n} L^{2*n} T^{-2*n}',f'M L² T^{-(n+1)}'],'Energy dimension ML²T⁻²। n power এবং time দ্বারা ভাগে MⁿL²ⁿT⁻(²ⁿ+¹)।'))
add(c,'percentage-calibration',lambda n:Q(f'ঘড়ি প্রতি actual 100 s-এ {100+n} s দেখায়। actual 1000 s elapsed হলে displayed time কত s?',10*(100+n),[1000+n,1000-n,F(100000,100+n)],'ঘড়ির rate=(100+n)/100 displayed second per actual second। 1000 s-এ দশগুণ display।'))

c='physics-1-02'
add(c,'cross-torque',lambda n:Q(f'r=({n},1,0) m, F=(0,2,3) N। torque-এর z-component কত N·m?',2*n,[3*n,-2*n,2*n+3],'Torque r×F। z-component rxFy−ryFx=n·2−1·0=2n; dot product নয়।'))
add(c,'work-angle',lambda n:Q(f'F=({n},2,0) N, displacement=(1,−{n},0) m। work কত J?',-n,[n,3*n,0],'Dot product F·s=n−2n=−n। বলের বিপরীত projected displacement negative work দেয়।'))
add(c,'relative-vector',lambda n:Q(f'A-এর velocity ({n},2), B-এর ({n},−2) m/s। A relative to B speed কত m/s?',4,[2,2*n,0],'Relative vector vA−vB=(0,4), norm 4। shared x-component পুরো cancel।'))
add(c,'resultant-orthogonal',lambda n:Q(f'পরস্পর লম্ব বল {3*n} ও {4*n} N N। resultant-এর magnitude কত?',5*n,[7*n,n,25*n*n],'Orthogonal resultant R=√((3n)²+(4n)²)=5n। সাধারণ যোগে 7n ভুল।'))
add(c,'perpendicular-resultants',lambda n:Q(f'|a|=|b|={n}, a ও b সমান্তরাল নয়। (a+b)·(a−b) কত?',0,[n*n,2*n*n,-2*n*n],'Dot distributivity-এ cross terms cancel: (a+b)·(a−b)=|a|²−|b|²=0।'))
add(c,'projection-unit',lambda n:Q(f'a=({n},4,0) এবং unit b=(3/5,4/5,0)। b-direction-এ a-এর scalar projection কত?',F(3*n+16,5),[F(4*n+12,5),3*n+16,F(3*n,5)],'Scalar projection a·b̂=n(3/5)+4(4/5)=(3n+16)/5; b ইতিমধ্যে unit।'))
add(c,'cross-direction',lambda n:Q(f'a=({n},0,0), b=(0,0,2)। a×b-এর direction কী?','−y direction',['+y direction','+z direction','+x direction'],'Right-hand rule i×k=−j। a×b=−2n j; n>0 হওয়ায় direction −y।'))
add(c,'inclination',lambda n:Q(f'এক velocity vector ({n},{n},0)। x-axis-এর সঙ্গে angle কত?','45°',['0°','90°','135°'],'দুই positive সমান component-এর tanθ=vy/vx=1। first quadrant থেকে θ=45°।'))
add(c,'angle-from-dot',lambda n:Q(f'|a|=|b|={n}, a·b=−{F(n*n,2)}। angle কত?','120°',['60°','90°','180°'],'cosθ=(a·b)/(|a||b|)=−½। তাই 0≤θ≤π-এ θ=120°।'))
add(c,'triple-volume',lambda n:Q(f'Edges a=({n},0,0), b=(1,2,0), c=(0,1,3) m। parallelepiped volume কত m³?',6*n,[3*n,2*n,12*n],'Volume=|a·(b×c)|। triangular matrix-এর determinant n·2·3=6n; skew components প্রভাব ফেলে না।'))

c='physics-1-03'
add(c,'two-stage-motion',lambda n:Q(f'Particle rest থেকে 2 m/s²-এ {n} s accelerate করে, তারপর same speed-এ 3 s চলে। total distance কত m?',n*n+6*n,[n*n+3*n,2*n*n+6*n,6*n],'Acceleration stage s₁=½at²=n², final v=2n। uniform stage s₂=v·3=6n; total যোগ।'))
add(c,'velocity-graph-crossing',lambda n:Q(f'v(t)={n}−2t m/s, 0≤t≤{n} s। total distance কত m?',F(n*n,2),[0,n*n,F(n*n,4)],'v=0 at n/2। v-t graph-এর দুই triangle area n²/4 করে; distance মোট n²/2।'),'hard','graph_reasoning')
add(c,'nth-second',lambda n:Q(f'Rest থেকে constant acceleration 4 m/s²। {n}-তম second-এ distance কত m?',4*n-2,[2*n*n,4*n,2*n-1],'s(n)−s(n−1)=2n²−2(n−1)²=4n−2। মোট distance আর nth-second distance আলাদা।'))
add(c,'catch-up',lambda n:Q(f'A t=0-এ constant 4 m/s-এ যায়। একই origin থেকে B rest-এ, acceleration 2 m/s², delay {n} s পরে শুরু। B start-এর τ পরে catch হলে কোন equation?','τ²=4(τ+'+str(n)+')',['τ²=4τ',f'2τ²=4(τ+{n})',f'τ²=4(τ−{n})'],'B-এর distance ½·2τ²=τ²। A-এর elapsed time τ+n, distance 4(τ+n); origins same।'),'hard','modelling')
add(c,'braking-distance',lambda n:Q(f'এক car speed {2*n} m/s থেকে 4 m/s² deceleration-এ থামে। stopping distance কত m?',F(n*n,2),[n*n,F(n,2),2*n*n],'v²=u²+2as; final 0, a=−4। s=u²/8=4n²/8=n²/2।'))
add(c,'average-speed-halves',lambda n:Q(f'একই distance-এর প্রথম half speed {n}, দ্বিতীয় half speed {2*n} m/s। average speed কত?',F(4*n,3),[F(3*n,2),n,2*n],'Equal distances-এ harmonic mean 2v₁v₂/(v₁+v₂)=4n/3। arithmetic mean শুধু equal times-এ।'))
add(c,'free-fall-last',lambda n:Q(f'Rest থেকে drop; g=10 m/s²। total fall time {n} s। শেষ 1 s-এ distance কত m?',10*n-5,[5*n*n,10*n,5*n],'s(n)−s(n−1)=5[n²−(n−1)²]=10n−5; total height 5n² নয়।'))
add(c,'projectile-energy-speed',lambda n:Q(f'Projectile initial velocity ({3*n},{4*n}) m/s। air resistance নেই। top-এ speed কত?',3*n,[4*n,5*n,0],'Top-এ vertical velocity 0, horizontal unchanged 3n। তাই speed=3n; পুরো velocity শূন্য নয়।'))
add(c,'acceleration-from-position',lambda n:Q(f'x(t)={n}t³−2t²+t। t=1-এ acceleration কত?',6*n-4,[3*n-4,6*n-2,n-1],'Velocity=3nt²−4t+1; acceleration=6nt−4। t=1-এ 6n−4; দুবার derivative লাগে।'))
add(c,'river-crossing',lambda n:Q(f'River width {3*n} m, current 4 m/s। boat-এর water-relative speed 3 m/s, সোজা bank-normal steer করে। drift কত m?',4*n,[3*n,5*n,F(9*n,4)],'Crossing time=width/normal speed=n s। current drift=4·n=4n; resultant speed দিয়ে crossing time নয়।'))

c='physics-1-04'
add(c,'atwood',lambda n:Q(f'Ideal Atwood: masses {n} kg ও {3*n} kg। g=10। heavier mass-এর acceleration কত m/s²?',5,[10,F(10,3),F(5,2)],'Combined system net force=(3n−n)g, inertial mass=4n। a=2ng/(4n)=g/2=5।'))
add(c,'elevator-scale',lambda n:Q(f'Mass {n} kg elevator-এ downward acceleration 2 m/s²। g=10। scale reading কত N?',8*n,[12*n,10*n,2*n],'Downward acceleration হলে mg−N=ma⇒N=m(g−a)=8n। accelerating downward আর moving downward একই নয়।'))
add(c,'inelastic-collision',lambda n:Q(f'Mass {n} kg speed 6 m/s, stationary mass {2*n} kg-এ লেগে একসঙ্গে চলে। final speed কত?',2,[3,6,4],'External impulse negligible; momentum n·6=(n+2n)v⇒v=2। kinetic energy conserved নয়।'))
add(c,'friction-pulley',lambda n:Q(f'Horizontal table-এ mass {n} kg, μk=0.2; pulley-তে hanging mass {n} kg। g=10, ideal rope। acceleration কত?',4,[5,8,2],'Driving force mg−μmg=8n N; total mass 2n। a=8n/(2n)=4 m/s²।'),'hard')
add(c,'centripetal-top',lambda n:Q(f'Vertical circle radius {n} m-এ rope just taut at top। g=10। minimum top speed² কত?',10*n,[20*n,50*n,0],'At threshold top tension=0। gravity alone provides mv²/r: mg=mv²/n⇒v²=10n।'))
add(c,'impulse-graph',lambda n:Q(f'Force-time graph triangular: base {n} s, peak 6 N। particle mass 3 kg। speed change magnitude কত?',n,[2*n,3*n,F(n,2)],'Impulse triangle area=½·n·6=3n N·s। Δv=J/m=3n/3=n।'))
add(c,'rocket-momentum',lambda n:Q(f'Initial stationary body mass {3*n} kg splits: part {n} kg goes +4 m/s। other part velocity কত?',-2,[2,-4,4],'Momentum zero: n·4+(2n)v=0⇒v=−2 m/s। sign opposite, mass total ধরে রাখতে হয়।'))
add(c,'static-friction',lambda n:Q(f'Mass {n} kg rough floor, μs=0.5, g=10। horizontal push {2*n} N, rest থাকে। actual friction কত N?',2*n,[5*n,0,10*n],'Static friction self-adjusts to balance applied force up to limit μsN=5n। actual friction 2n, maximum নয়।'))
add(c,'collision-loss',lambda n:Q(f'Equal masses {n} kg, one at speed 4 m/s অন্য rest। stick together। lost kinetic energy কত J?',4*n,[8*n,2*n,0],'Momentum gives final speed 2। initial K=8n, final K=½·2n·4=4n। loss=4n J।'))
add(c,'banking-angle',lambda n:Q(f'Frictionless banked road radius {n} m, tanθ=1/2, g=10। design speed² কত?',5*n,[10*n,20*n,F(n,2)],'Components Ncosθ=mg, Nsinθ=mv²/r। divide: tanθ=v²/(rg)⇒v²=5n।'))

c='physics-1-05'
add(c,'variable-force-work',lambda n:Q(f'F(x)=2x N, mass {n} kg rest থেকে x=0→3 m। final speed² কত?',F(18,n),[F(9,n),18*n,9],'Work ∫₀³2x dx=9 J。 work-energy ½mv²=9⇒v²=18/n।'),'hard')
add(c,'rough-incline-energy',lambda n:Q(f'Mass {n} kg 5 m incline দিয়ে নিচে নামে; sinθ=3/5, cosθ=4/5, μk=0.25,g=10। rest থেকে final speed² কত?',40,[60,20,80],'Potential loss=mg·3=30n J; friction work=μmgcosθ·5=10n। net K=20n⇒v²=40।'),'hard')
add(c,'spring-energy-double',lambda n:Q(f'Spring k={2*n} N/m। 1 m থেকে 3 m stretch করতে work কত J?',8*n,[9*n,4*n,2*n],'ΔU=½k(3²−1²)=½·2n·8=8n। final energy আর additional work পৃথক।'))
add(c,'pump-efficiency',lambda n:Q(f'Pump input {100*n} W, efficiency 60%; height 10 m, g=10। water flow mass rate কত kg/s?',F(3*n,5),[n,F(5*n,3),F(3*n,50)],'Output power=60n W। lifting power ṁgh=100ṁ⇒ṁ=0.6n kg/s।'))
add(c,'power-force-speed',lambda n:Q(f'Motor constant mechanical power {6*n} W। speed 3 m/s-এ force কত N?',2*n,[18*n,F(n,2),6*n],'Instantaneous power P=Fv for parallel force/velocity। তাই F=P/v=2n।'))
add(c,'momentum-energy-ratio',lambda n:Q(f'একই mass-এর momentum {n} গুণ করলে kinetic energy কত গুণ?',n*n,[n,2*n,F(1,n)],'Nonrelativistic K=p²/(2m)। mass স্থির হলে K scales as momentum squared: factor n²।'))
add(c,'conservative-potential',lambda n:Q(f'U(x)={n}x²−4x J। x=1 m-এ force কত N?',4-2*n,[2*n-4,4-n,2*n+4],'Conservative force F=−dU/dx=−(2nx−4)। x=1-এ 4−2n; minus gradient জরুরি।'))
add(c,'vertical-loop-minimum',lambda n:Q(f'Radius {n} m frictionless vertical loop। bottom-এ minimum speed² কত যেন top-এ contact থাকে? g=10',50*n,[10*n,40*n,20*n],'Top threshold vtop²=gr। bottom→top energy: vbottom²=vtop²+4gr=5gr=50n।'),'hard')
add(c,'collision-energy-fraction',lambda n:Q(f'Mass m at speed {n} m/s stationary identical mass-এর সঙ্গে perfectly inelastic collision করে। final/initial total kinetic energy ratio কত?',F(1,2),[1,F(1,4),0],'Momentum থেকে common v=u/2। final K=½·2m(u/2)²=mu²/4; initial mu²/2; ratio ½।'))
add(c,'energy-height-speed',lambda n:Q(f'Rest থেকে height {3*n} m drop। ground-এর উপরে {n} m-এ speed² কত? g=10',40*n,[60*n,20*n,10*n],'Fallen height=3n−n=2n। energy conservation v²=2gΔh=40n; remaining height নয়।'))

c='physics-1-06'
add(c,'orbit-energy',lambda n:Q(f'Circular orbit-এ potential energy U=−{4*n} J। total mechanical energy কত J?',-2*n,[-4*n,2*n,0],'Circular orbit virial relation K=−U/2=2n। total E=K+U=−2n=U/2।'))
add(c,'gravity-altitude',lambda n:Q(f'Planet radius R, surface g={n} m/s²। height R-এ gravitational acceleration কত?',F(n,4),[F(n,2),n,F(n,8)],'Distance from centre r=2R। g(r)=g₀(R/r)²=g₀/4=n/4; height centre-distance নয়।'))
add(c,'gravity-depth',lambda n:Q(f'Uniform-density planet-এ surface g={n}। surface-এর R/4 নিচে g কত?',F(3*n,4),[F(n,4),F(16*n,9),n],'ভিতরে enclosed mass ∝r³, g∝r। depth R/4⇒r=3R/4⇒g=¾g₀।'))
add(c,'escape-circular',lambda n:Q(f'একই radius-এ circular orbital speed {n} m/s। escape speed² কত?',2*n*n,[n*n,4*n*n,2*n],'vorb²=GM/r ও vesc²=2GM/r। তাই escape speed²=2n², speed √2 গুণ।'))
add(c,'kepler-radius',lambda n:Q(f'এক planet-এর দুই circular satellite orbit radius R ও 4R। প্রথম period {n} h। দ্বিতীয় period কত h?',8*n,[4*n,16*n,2*n],'Kepler T²∝r³⇒T₂/T₁=(4)^(3/2)=8। radius linear period নয়।'))
add(c,'potential-difference',lambda n:Q(f'Planet-এর GM/R={n} J/kg। surface থেকে radius 2R-এ প্রতি kg তুলতে work কত?',F(n,2),[n,2*n,-F(n,2)],'Potential V=−GM/r। ΔV=−GM/(2R)+GM/R=GM/(2R)=n/2; quasistatic external work positive।'))
add(c,'two-planet-surface',lambda n:Q(f'Planet A mass M radius R, B mass {4*n}M radius {2*n}R। gB/gA কত?',F(1,n),[n,F(2,n),4*n],'g=GM/R²। ratio (4n)/(2n)²=1/n; radius squared লাগে।'))
add(c,'zero-field-position',lambda n:Q(f'Masses M ও 4M, separation {3*n} m। তাদের মাঝে M থেকে কত দূরে net field zero?',n,[2*n,F(3*n,2),F(n,2)],'GM/x²=4GM/(3n−x)²⇒3n−x=2x⇒x=n। ছোট mass-এর কাছে balance।'))
add(c,'satellite-work-speed',lambda n:Q(f'Circular satellite-এর speed {n} m/s। force-এর instantaneous power কত W?','0',['mv²/r','mv³/r','mgn'],'Gravity radial এবং velocity tangential, তাই F·v=0। force কাজ না করেও velocity direction বদলায়।'),'medium','conceptual')
add(c,'escape-density-radius',lambda n:Q(f'একই density-এর spherical planets A radius R, B radius {n}R। escape speed ratio B/A কত?',n,[n*n,F(1,n),1],'Mass∝ρR³, vesc²∝M/R∝R²। same density-এ vesc∝R, ratio n।'))

c='physics-1-07'
add(c,'wire-energy',lambda n:Q(f'Wire linear-elastic stretch-এ force 0→{4*n} N, extension 0→0.01 m। stored energy কত J?',F(n,50),[F(n,25),F(n,100),4*n],'Elastic energy=½Fmax ΔL=½·4n·0.01=0.02n J; variable force-এর average লাগে।'))
add(c,'parallel-wire-extension',lambda n:Q(f'Same material/length-এর wires area A ও 3A parallel-এ load {n} N বহন করে। thick wire-এর load কত?',F(3*n,4),[F(n,4),F(n,3),n],'Parallel wires-এর extension ও strain equal; stress Yε equal। force∝area⇒thick share 3/4 total।'))
add(c,'capillary-ratio',lambda n:Q(f'Same liquid wetting tubes radii r ও {n}r। rise height ratio first/second কত?',n,[F(1,n),n*n,1],'Jurin law h=2Tcosθ/(ρgr)। same liquid/contact angle-এ h∝1/r; ratio=n।'))
add(c,'drop-pressure',lambda n:Q(f'Liquid drop radius {n} mm, surface tension 0.03 N/m। excess pressure কত Pa?',F(60,n),[F(120,n),F(30,n),60*n],'Single liquid surface ΔP=2T/r=0.06/(n×10⁻³)=60/n Pa; soap bubble হলে factor 4।'))
add(c,'soap-bubble-work',lambda n:Q(f'Soap bubble radius r→2r করতে surface tension T constant। r²T={n} J। work/π কত J?',24*n,[12*n,8*n,32*n],'Bubble two surfaces: U=2T·4πr²=8πTr²। ΔU=8πT(4r²−r²)=24πn।'),'hard')
add(c,'viscosity-terminal',lambda n:Q(f'Stokes regime-এ একই material-এর sphere radius r ও {n}r। terminal speed ratio second/first কত?',n*n,[n,F(1,n*n),1],'Drag 6πηrv, effective weight∝r³। balance থেকে terminal v∝r²; ratio n²।'))
add(c,'buoyancy-fraction',lambda n:Q(f'Object density {n*100} kg/m³, liquid {n*200} kg/m³। floating volume fraction submerged কত?',F(1,2),[1,F(1,4),2],'Floating equilibrium ρobject Vg=ρliquid Vsub g। Vsub/V=ρobject/ρliquid=½।'))
add(c,'poiseuille-resistance',lambda n:Q(f'Laminar flow tube length L→{n}L, radius r→2r, same viscosity। hydraulic resistance ratio new/old কত?',F(n,16),[F(n,4),16*n,F(16,n)],'Poiseuille R∝L/r⁴। ratio=n/(2⁴)=n/16; radius squared নয় fourth power।'))
add(c,'bulk-compression',lambda n:Q(f'Bulk modulus B={n}×10⁹ Pa। pressure increase 2×10⁶ Pa। |ΔV|/V কত?',F(1,500*n),[F(1,50*n),F(n,500),F(2,n)],'Bulk modulus B=−ΔP/(ΔV/V)। compression fraction=ΔP/B=2×10⁶/(n×10⁹)=1/(500n)।'))
add(c,'wire-radius-effect',lambda n:Q(f'Wire load F, length L, radius r-এ extension x। radius {n}r করলে same F,L extension কত?',f'x/{n*n}',[f'x/{n}',f'{n*n}x','x'],'ΔL=FL/(YA), area πr²। radius n গুণে area n²; extension x/n²।'))

c='physics-1-08'
add(c,'energy-at-fraction',lambda n:Q(f'SHM total energy {4*n} J। displacement A/2-এ kinetic energy কত J?',3*n,[n,2*n,4*n],'Potential fraction x²/A²=¼। kinetic fraction 1−¼=¾; K=3n J।'))
add(c,'spring-cut',lambda n:Q(f'Uniform spring-এর k={n} N/m। সমান দুই piece-এর একটিতে একই mass ঝুলালে period ratio new/old কত?','1/√2',['√2','1/2','2'],'Uniform spring k∝1/length; half length-এর k′=2k। T∝1/√k⇒ratio=1/√2।'))
add(c,'combined-springs',lambda n:Q(f'Springs k₁={n}, k₂={2*n} N/m series-এ mass m। effective k কত?',F(2*n,3),[3*n,F(n,3),2*n],'Series 1/keff=1/k₁+1/k₂=3/(2n)⇒keff=2n/3; parallel sum নয়।'))
add(c,'pendulum-elevator',lambda n:Q(f'Pendulum period T stationary elevator-এ। elevator upward acceleration g/{n} হলে period ratio new/old কত?',f'√({n}/{n+1})',[f'√({n+1}/{n})',f'{n}/{n+1}','1'],'Effective g′=g+a=g(1+1/n)। T′/T=√(g/g′)=√(n/(n+1))।'))
add(c,'shm-phase',lambda n:Q(f'x=Acos({n}t+π/3)। t=0-এ v/(Aω) কত?','−√3/2',['√3/2','1/2','−1/2'],'v=−Aω sin(ωt+π/3)। at 0 ratio=−sinπ/3=−√3/2; phase/sign দুটোই গুরুত্বপূর্ণ।'))
add(c,'spring-added-mass',lambda n:Q(f'Spring oscillator mass m period T। mass {n*n}m করলে new period কত?',f'{n}T',[f'{n*n}T',f'T/{n}','T'],'T=2π√(m/k); mass factor n² gives period factor n। amplitude period-এ আসে না।'))
add(c,'velocity-half',lambda n:Q(f'SHM amplitude {2*n} cm, angular speed 3 rad/s। displacement {n} cm-এ speed² কত cm²/s²?',27*n*n,[36*n*n,9*n*n,18*n*n],'v²=ω²(A²−x²)=9(4n²−n²)=27n²; potential energy বাদ দিতে হয়।'))
add(c,'acceleration-position',lambda n:Q(f'SHM-এ x=0.02 m-এ acceleration −{2*n} m/s²। ω² কত s⁻²?',100*n,[F(n,100),n,50*n],'a=−ω²x⇒ω²=(2n)/0.02=100n; restoring sign correctly removed।'))
add(c,'time-quarter',lambda n:Q(f'SHM period {4*n} s। positive extreme থেকে প্রথম equilibrium পৌঁছাতে সময় কত s?',n,[2*n,4*n,F(n,2)],'Extreme→equilibrium phase change π/2, full cycle 2π। তাই time T/4=n s।'))
add(c,'pendulum-length-change',lambda n:Q(f'Pendulum period {n} s। length 44% বাড়ালে period কত s?',F(6*n,5),[F(36*n,25),F(11*n,5),F(5*n,6)],'Length factor 1.44; T factor √1.44=1.2। new T=6n/5, 44% period increase নয়।'))

c='physics-1-09'
add(c,'doppler-both-moving',lambda n:Q(f'Sound v=340 m/s। source 20 m/s ও listener 10 m/s পরস্পরের দিকে আসে; emitted f={32*n} Hz। heard f কত?',35*n,[34*n,33*n,30*n],'Approach দুদিকে: f′=f(v+vo)/(v−vs)=32n·350/320=35n। numerator ও denominator signs ভিন্ন।'),'hard')
add(c,'standing-string-mode',lambda n:Q(f'String length 1 m, wave speed {20*n} m/s। third harmonic frequency কত Hz?',30*n,[10*n,20*n,60*n],'Both ends fixed: fn=nmode v/(2L)। third harmonic=3·20n/2=30n; parameter n harmonic index নয়।'))
add(c,'closed-pipe-next-mode',lambda n:Q(f'Closed-open pipe fundamental {n} Hz। পরের resonance frequency কত Hz?',3*n,[2*n,4*n,F(n,2)],'Closed pipe only odd harmonics supports; fundamental-এর পর third harmonic 3f₁, second harmonic নয়।'))
add(c,'beats-inverse',lambda n:Q(f'Unknown fork-এর সঙ্গে 200 Hz fork-এ {n} beats/s। unknown fork-এ wax দিলে beats কমে। original frequency কত?',200+n,[200-n,n,400+n],'Wax mass বাড়িয়ে unknown frequency কমায়। beats কমেছে মানে unknown প্রথমে 200-এর উপরে ছিল: 200+n।'))
add(c,'intensity-db',lambda n:Q(f'Intensity I→{10**(n%3+1)}I। sound level increase কত dB?',10*(n%3+1),[n%3+1,20*(n%3+1),100*(n%3+1)],'Δβ=10log₁₀(I₂/I₁)। factor 10ᵏ হলে increase 10k dB, amplitude formula factor20 এখানে নয়।'))
add(c,'wave-phase-distance',lambda n:Q(f'Wavelength {n} m। একই সময়ে separation {F(n,4)} m-এর phase difference কত?','π/2',['π/4','π','2π'],'Spatial phase difference Δφ=2πΔx/λ=2π·¼=π/2; time fixed বলে শুধু spatial term।'))
add(c,'string-density-tension',lambda n:Q(f'Tension factor {n*n}, linear density factor 4 হলে wave speed ratio new/old কত?',F(n,2),[2*n,F(n*n,4),F(2,n)],'v=√(T/μ); ratio=√(n²/4)=n/2, square root নিতে হয়।'))
add(c,'energy-amplitude',lambda n:Q(f'Same medium/frequency-তে amplitude A→{n}A। wave intensity factor কত?',n*n,[n,F(1,n),2*n],'Intensity energy flux; harmonic wave-এ I∝A²ω²। same frequency বলে factor n²।'))
add(c,'superposition-phase',lambda n:Q(f'Equal amplitude {n} mm-এর দুই coherent wave phase difference 120°। resultant amplitude কত mm?',n,[2*n,0,n*n],'Resultant 2A|cos(φ/2)|=2n cos60°=n। intensity যোগ সরাসরি amplitude দেয় না।'))
add(c,'two-end-node-count',lambda n:Q(f'Fixed-fixed string-এর {n}-তম harmonic-এ endpointsসহ node কতটি?',n+1,[n,n-1,2*n],'n half-wavelength string-এ থাকে; segment boundary-তে node। endpointsসহ n+1 node, antinode n।'))

c='physics-1-10'
add(c,'mixture-rms-energy',lambda n:Q(f'Same T-তে gases molar masses {n} ও {4*n} g/mol। mean translational KE ratio first/second কত?',1,[2,4,F(1,2)],'Mean translational energy per molecule 3kT/2, molar mass-independent। rms speed differs but KE একই।'))
add(c,'gas-transform',lambda n:Q(f'Fixed amount gas: T factor {n}, pressure factor 2। volume ratio final/initial কত?',F(n,2),[2*n,F(2,n),n],'PV=nRT-এ fixed gas amount হলে V∝T/P। ratio=T₂/T₁×P₁/P₂=n/2; T Kelvin।'))
add(c,'pressure-kinetic',lambda n:Q(f'Gas density {n} kg/m³, rms speed 30 m/s। pressure কত Pa?',300*n,[900*n,450*n,30*n],'Kinetic theory P=⅓ρ vrms²=⅓·n·900=300n। mean speed ব্যবহার করা যাবে না।'))
add(c,'degrees-freedom',lambda n:Q(f'{n} mol ideal diatomic gas, vibrational modes frozen। U/(RT) কত?',F(5*n,2),[F(3*n,2),F(7*n,2),5*n],'Diatomic rigid molecule-এর degrees f=5। internal energy U=(f/2)nRT=(5n/2)RT।'))
add(c,'density-pressure-temperature',lambda n:Q(f'Same ideal gas pressure 3P, temperature {n}T হলে density ratio new/old কত?',F(3,n),[3*n,F(n,3),F(1,n)],'ρ=PM/(RT)। same M-এ density∝P/T, তাই ratio 3/n; absolute T দরকার।'))
add(c,'rms-temperature',lambda n:Q(f'Gas rms speed {n} গুণ করতে absolute temperature কত গুণ চাই?',n*n,[n,F(1,n),2*n],'vrms=√(3RT/M)। same gas-এ v∝√T; speed factor n gives temperature factor n²।'))
add(c,'partition-pressure',lambda n:Q(f'Volume V,T-তে {n} mol gas A ও {2*n} mol অর্থ 2×{n} mol gas B। total P। A-এর partial pressure ও total pressure-এর অনুপাত PA/P কত?',F(1,3),[F(2,3),1,F(1,n)],'Dalton: PA/P=nA/(nA+nB)=n/(3n)=⅓। বিকল্পগুলো PA/P-এর মান।'))
add(c,'number-density',lambda n:Q(f'Ideal gas P={n}×10⁵ Pa,T=300 K। number density N/V কোনটি? k Boltzmann constant',f'{n}×10⁵/(300k)',[f'{300*n}×10⁵/k',f'{n}×10⁵k/300',f'300k/({n}×10⁵)'],'Microscopic ideal gas PV=NkT। divide V,T,k: N/V=P/(kT); molar R দিয়ে molecule count নয়।'))
add(c,'adiabatic-gamma',lambda n:Q(f'Ideal monatomic gas {n} mol। Cp/Cv কত?',F(5,3),[F(7,5),F(3,2),1],'Monatomic f=3⇒Cv=3R/2, Cp=Cv+R=5R/2। gamma=5/3; amount cancel।'))
add(c,'gas-wall-speed',lambda n:Q(f'Fixed N,V gas-এর all molecular speeds {n} গুণ হলে pressure factor কত?',n*n,[n,F(1,n),1],'P=⅓(Nm/V)〈v²〉। same number density-এ mean-square speed n² গুণ, pressureও n²।'))

c='physics-2-01'
add(c,'first-law-cycle',lambda n:Q(f'Cycle-এ heat absorbed {5*n} J, rejected {3*n} J। net work by gas কত J?',2*n,[8*n,5*n,-2*n],'Cycle শেষে internal energy change zero। net work=net heat=Qin−Qout=2n J।'))
add(c,'isothermal-compression',lambda n:Q(f'Ideal gas reversible isothermal V→V/2; nRT={n} J। work by gas কত?',f'−{n}ln2',[f'{n}ln2',f'−{n}',0],'Work by gas W=nRT ln(V₂/V₁)=n ln(½)=−nln2। compression-এ gas-এর work negative।'))
add(c,'carnot-cold',lambda n:Q(f'Carnot engine Th={100*n} K,Tc={50*n} K। efficiency কত %?',50,[25,75,100],'Carnot efficiency η=1−Tc/Th=1−½=½। Kelvin ratios, Celsius নয়।'))
add(c,'adiabatic-expansion-energy',lambda n:Q(f'Adiabatic expansion-এ gas {n} J work করে। ΔU কত J?',-n,[n,0,2*n],'Q=0 এবং convention ΔU=Q−Wby। তাই ΔU=−n; expansion-এ internal energy কমে।'))
add(c,'refrigerator-cop',lambda n:Q(f'Refrigerator cold side থেকে {3*n} J heat নেয়, input work {n} J। hot side-এ heat কত J?',4*n,[2*n,3*n,n],'Energy conservation Qhot=Qcold+Win=4n। COP=3 কিন্তু rejected heat 4n J।'))
add(c,'isochoric-heat',lambda n:Q(f'{n} mol ideal monatomic gas constant volume-এ ΔT=20 K। Q/R কত mol·K?',30*n,[50*n,20*n,0],'At constant volume W=0; Q=ΔU=nCvΔT=n(3R/2)20=30nR।'))
add(c,'entropy-isothermal',lambda n:Q(f'Reversible isothermal expansion V→2V of {n} mol ideal gas। ΔS/R কত?',f'{n}ln2',[f'−{n}ln2',str(n),'0'],'ΔS=Qrev/T=nRln(V₂/V₁)=nRln2। temperature constant মানে entropy constant নয়।'))
add(c,'adiabatic-temperature',lambda n:Q(f'Monatomic ideal gas reversible adiabatic; V→8V,Tinitial={4*n} K। Tfinal কত K?',n,[2*n,8*n,F(n,2)],'TV^(γ−1)=constant, γ=5/3। T₂/T₁=8^(-2/3)=¼; T₂=n।'))
add(c,'engine-power-rate',lambda n:Q(f'Engine efficiency 40%, input heat rate {100*n} W। rejected heat rate কত W?',60*n,[40*n,140*n,100*n],'Work rate=ηQin=40n W। rejected rate=Qin−W=60n; efficiency remaining heat fraction নয়।'))
add(c,'pv-area-work',lambda n:Q(f'P-V rectangle cycle pressure 2P→5P, volume V→3V; clockwise। PV={n} J। net work কত J?',6*n,[-6*n,10*n,3*n],'Cycle work enclosed area ΔPΔV=(3P)(2V)=6PV=6n J। clockwise positive work by gas।'))

c='physics-2-02'
add(c,'capacitor-insert-isolated',lambda n:Q(f'Isolated capacitor C, voltage {n} V। fully insert dielectric κ=3। new voltage কত V?',F(n,3),[3*n,n,F(n,9)],'Isolated হলে charge Q constant; C′=3C। V′=Q/C′=V/3=n/3; battery connected নয়।'))
add(c,'capacitor-energy-battery',lambda n:Q(f'Battery-connected capacitor initially energy {n} J। dielectric κ=2 fully insert; battery stays। new stored energy কত J?',2*n,[F(n,2),n,4*n],'Battery fixes V। U=½CV², C doubles⇒U doubles। isolated constant-Q case-এ opposite ratio।'))
add(c,'series-charge',lambda n:Q(f'Capacitors {n} μF ও {2*n} μF series, total 6 V। small capacitor voltage কত?',4,[2,6,3],'Series Q equal; voltage inversely proportional C। ratio Vsmall:Vlarge=2:1, sum6⇒4V,2V।'))
add(c,'zero-potential',lambda n:Q(f'Charges +Q at x=0, −2Q at x={3*n} m। between charges potential zero point-এর x কত?',n,[2*n,F(3*n,2),F(n,2)],'Potential scalar: kQ/x−2kQ/(3n−x)=0⇒3n−x=2x⇒x=n। electric field সেখানে zero নয়।'))
add(c,'field-from-potential',lambda n:Q(f'V(x)={n}x²−6x volts। x=2 m-এ Ex কত V/m?',6-4*n,[4*n-6,2*n-6,6+4*n],'Electric field Ex=−dV/dx=−2nx+6। x=2 দিলে 6−4n; negative gradient sign জরুরি।'))
add(c,'dipole-torque-energy',lambda n:Q(f'Dipole pE={2*n} J। parallel থেকে 60° rotate করতে external quasistatic work কত?',n,[2*n,3*n,-n],'Dipole U=−pEcosθ। ΔU=−pE/2−(−pE)=pE/2=n; no kinetic change।'))
add(c,'force-ratio-distance',lambda n:Q(f'Coulomb force F। charge one doubles, separation {n} গুণ হলে new force/F কত?',F(2,n*n),[F(2,n),2*n*n,F(1,n*n)],'Coulomb F∝q₁q₂/r²। numerator factor2, distance denominator n²⇒2/n²।'))
add(c,'conducting-sphere-potential',lambda n:Q(f'Charged conducting sphere radius R, surface potential {n} V। centre potential কত?',n,[0,2*n,F(n,2)],'Electrostatic equilibrium conductor interior E=0, potential uniform and equal surface। centre potential n V, field zero মানে potential zero নয়।'))
add(c,'capacitor-parallel',lambda n:Q(f'{n} μF ও 3 μF parallel-এ, initially both uncharged। 2 V battery দিলে total charge কত μC?',2*n+6,[2*n+3,n+3,F(6*n,n+3)],'Parallel equivalent C=n+3 μF; same voltage 2V। total Q=CeqV=2n+6 μC।'))
add(c,'gauss-enclosed',lambda n:Q(f'Closed surface মোট electric flux {n}/ε₀। enclosed charge কত?',n,[F(1,n),0,n*n],'Gauss law ΦE=Qenclosed/ε₀⇒Qenclosed=n। surface-এর বাইরের charges net flux-এ অবদান zero।'))

c='physics-2-03'
add(c,'emf-internal',lambda n:Q(f'Cell emf {3*n} V, internal resistance 1Ω, external resistance 2Ω। terminal voltage কত V?',2*n,[3*n,n,F(3*n,2)],'Current I=ε/(R+r)=n A। terminal V=IR=2n=ε−Ir; emf-এর সমান নয় under load।'))
add(c,'balanced-bridge',lambda n:Q(f'Wheatstone bridge resistors P={n}Ω,Q=2Ω,R={3*n}Ω,S=?। balance-এর S কত Ω?',6,[3,2*n,6*n],'Balance P/Q=R/S⇒n/2=3n/S⇒S=6Ω; bridge galvanometer current zero।'))
add(c,'wire-stretch-resistance',lambda n:Q(f'Wire volume ও resistivity constant; length {n} গুণ stretch। Rnew/Rold কত?',n*n,[n,F(1,n),1],'Volume AL constant⇒area A/n। R=ρL/A⇒factor n/(1/n)=n²।'))
add(c,'voltage-divider-load',lambda n:Q(f'{n}Ω ও {n}Ω series across 12V। দ্বিতীয় resistor-এর parallel-এ আরও {n}Ω load দিলে load voltage কত V?',4,[6,8,12],'Loaded second branch Req=n/2; total 3n/2। divider voltage 12·(n/2)/(3n/2)=4V।'),'hard')
add(c,'maximum-power',lambda n:Q(f'Cell emf {n} V ও internal r=2Ω। variable external R-এ maximum delivered power কত W?',F(n*n,8),[F(n*n,2),F(n*n,4),F(n,8)],'P=ε²R/(R+r)²; maximum R=r। Pmax=ε²/(4r)=n²/8; total circuit power নয়।'),'hard')
add(c,'parallel-series-power',lambda n:Q(f'Two equal R={n}Ω resistor same voltage source-এ একবার series, একবার parallel। Pparallel/Pseries কত?',4,[2,F(1,4),1],'Series Req=2R, parallel Req=R/2। at fixed V,P=V²/Req⇒ratio=4।'))
add(c,'heater-series-rating',lambda n:Q(f'Identical 220V heater resistance {n}Ω। two series on 220V; প্রতিটির power/একটি একা on220V power কত?',F(1,4),[F(1,2),2,4],'Series equal ভাগে each 110V। P∝V² same R, ratio=(110/220)²=¼।'))
add(c,'potentiometer-internal',lambda n:Q(f'Cell emf balance length {3*n} cm, terminal balance length {2*n} cm under external R=4Ω। internal r কত Ω?',2,[4,F(4,3),6],'ε/V=l₁/l₂=3/2=(R+r)/R। r=R(l₁/l₂−1)=4·½=2Ω।'),'hard')
add(c,'drift-area',lambda n:Q(f'Same metal/current wire cross-section A→{n}A। drift speed ratio new/old কত?',F(1,n),[n,n*n,1],'I=neAvd; ncarrier ও I স্থির। vd inversely proportional area; factor1/n।'))
add(c,'temperature-resistance',lambda n:Q(f'R₀={n}Ω at0°C, α=0.004°C⁻¹। at50°C R কত Ω?',F(6*n,5),[F(4*n,5),F(7*n,5),50*n],'R=R₀(1+αΔT)=n(1+0.2)=1.2n। coefficient dimension ব্যবহার করতে হয়।'))

c='physics-2-04'
add(c,'charged-orbit',lambda n:Q(f'Charged particle momentum {n} kg·m/s, |q|=2 C,B=3 T; v⊥B। orbit radius কত m?',F(n,6),[6*n,F(n,3),F(2*n,3)],'Magnetic centripetal balance |q|vB=mv²/r⇒r=p/(|q|B)=n/6।'))
add(c,'velocity-selector',lambda n:Q(f'Crossed fields E={3*n} V/m,B=3T। undeflected particle speed কত m/s?',n,[3*n,9*n,F(n,3)],'Opposite electric/magnetic forces cancel qE=qvB⇒v=E/B=n। charge ও mass cancel।'))
add(c,'wire-force-direction',lambda n:Q(f'Current {n} A +x-এ, length 2m, B=3T +z-এ। force direction কোনটি?','−y',['+y','+z','−x'],'F=I L×B। i×k=−j, magnitude6nN। direction cross product order-sensitive।'))
add(c,'field-wire-ratio',lambda n:Q(f'Long straight wire current I→2I, distance r→{n}r। Bnew/Bold কত?',F(2,n),[2*n,F(2,n*n),F(n,2)],'B=μ₀I/(2πr)। current linear, distance inverse first power; ratio2/n।'))
add(c,'coil-torque',lambda n:Q(f'Coil magnetic moment μ={n} A·m², B=2T, normal makes30° with B। torque কত N·m?',n,[2*n,0,n*n],'Torque μBsinθ=n·2·½=n। θ normal-এর angle, plane-এর angle নয়।'))
add(c,'helical-pitch',lambda n:Q(f'Particle cyclotron period 2s, B-parallel speed {n} m/s। helix pitch কত m?',2*n,[n,F(n,2),n*n],'Pitch=parallel distance travelled in one cyclotron period=vp T=2n। parallel component unchanged।'))
add(c,'magnetic-work',lambda n:Q(f'Particle charge {n} C uniform static B-এ moves, electric field নেই। magnetic force-এর কাজ কত?',0,[n,2*n,n*n],'Magnetic force qv×B always perpendicular to velocity। P=F·v=0; speed/kinetic energy অপরিবর্তিত।'))
add(c,'solenoid-field',lambda n:Q(f'Ideal long solenoid winding density {n} turns/m, current2A। B/μ₀ কত A/m?',2*n,[n,F(n,2),n*n],'Long-solenoid field B=μ₀nturn I=2μ₀n। total turns নয় turns per unit length দরকার।'))
add(c,'two-wire-force',lambda n:Q(f'Parallel long wires same direction currents I ও {n}I, separation d। attraction নাকি repulsion?','আকর্ষণ',['বিকর্ষণ','শূন্য force','দিক alternating'],'Same-direction parallel currents attract; opposite currents repel। current ratio magnitude বদলায়, sign নয়।'))
add(c,'cyclotron-energy-frequency',lambda n:Q(f'Nonrelativistic particle একই B-এ kinetic energy {n*n} গুণ করলে cyclotron frequency ratio কত?',1,[n,n*n,F(1,n)],'ωc=|q|B/m, nonrelativistic mass constant। energy/radius বদলালেও frequency energy-independent।'))

