add(c,'motional-emf',lambda n:Q(f'Rod length0.5m, B=2T, perpendicular speed {n}m/s। motional emf কত V?',n,[2*n,F(n,2),n*n],'Rod, velocity ও field mutually perpendicular⇒ε=Blv=2·0.5·n=n V।'))
add(c,'rl-time-energy',lambda n:Q(f'Inductor L=2H, current {n}A। stored magnetic energy কত J?',n*n,[2*n*n,n,F(n*n,2)],'Magnetic energy U=½LI²=½·2·n²=n²। current double করলে energy fourfold।'))
add(c,'rl-growth',lambda n:Q(f'RL current reaches (1−e⁻¹) of final value at t={n}s। R=2Ω। L কত H?',2*n,[F(n,2),n,4*n],'RL growth I=I∞(1−e^(−t/τ))। fraction1−e⁻¹ at t=τ=L/R; L=Rτ=2n।'))
add(c,'rms-peak',lambda n:Q(f'AC voltage v(t)={n}sinωt V। resistive R=2Ω। average power কত W?',F(n*n,4),[F(n*n,2),n*n,F(n,2)],'Peak n, rms=n/√2। P=Vrms²/R=(n²/2)/2=n²/4; peak-squared power double হয়।'))
add(c,'rlc-resonance',lambda n:Q(f'Series RLC-এ L={n}H,C=1/{n}F। resonance angular frequency কত rad/s?',1,[n,n*n,F(1,n)],'Resonance XL=XC⇒ω²LC=1। LC=n·1/n=1⇒ω₀=1rad/s।'))
add(c,'transformer-load',lambda n:Q(f'Ideal transformer turns Np:Ns=3:1, primary220V। secondary current {n}A। primary current কত A?',F(n,3),[3*n,n,F(n,9)],'Ideal power conservation VpIp=VsIs। voltage step-down3 gives primary current Is/3=n/3।'))
add(c,'flux-change-sign',lambda n:Q(f'10-turn coil positive flux through each turn Φ(t)={n}t² Wb। t=1s-এ induced emf কত V?',-20*n,[20*n,-10*n,10*n],'Faraday ε=−N dΦ/dt=−10·2nt। t=1⇒−20nV; signed orientation অনুযায়ী Lenz minus।'))
add(c,'impedance-components',lambda n:Q(f'Series circuit R={3*n}, XL={5*n}, XC={1*n} Ω। impedance magnitude কত Ω?',5*n,[9*n,7*n,n],'Net reactance XL−XC=4n। Z=√(R²+(XL−XC)²)=√(9n²+16n²)=5n।'))
add(c,'power-factor',lambda n:Q(f'Series AC: R={3*n}Ω, net reactance{4*n}Ω। power factor কত?',F(3,5),[F(4,5),1,F(3,4)],'Impedance Z=5n। cosφ=R/Z=3/5; reactive power alone active dissipation দেয় না।'))
add(c,'capacitive-frequency',lambda n:Q(f'Capacitor reactance X at frequency f। frequency {n}f হলে reactance কত?',f'X/{n}',[f'{n}X',f'X/{n*n}','X'],'XC=1/(2πfC)। same C-এ f factor n হলে reactance inverse factor1/n; inductor opposite।'))

c='physics-2-06'
add(c,'lens-two-in-series',lambda n:Q(f'Thin lens powers +{n} D ও −2 D in contact। equivalent focal length কত m?',F(1,n-2),[n-2,F(1,n+2),F(1,2-n)],'In-contact lens powers add: P=n−2 D। f=1/P metres; f values সরাসরি যোগ নয়।'))
