add(c,'lens-magnification',lambda n:Q(f'Converging lens f={n}cm, object distance {3*n}cm। image magnification signed কত?',F(-1,2),[F(1,2),-2,2],'Lens formula image distance1.5n। real inverted image m=−v/u=−(1.5n)/(3n)=−½।'))
add(c,'apparent-depth',lambda n:Q(f'Water index4/3। bottom apparent depth {3*n}m near normal viewing। real depth কত m?',4*n,[F(9*n,4),3*n,F(4*n,3)],'Near-normal apparent depth=real depth/μ। real=μ·apparent=(4/3)·3n=4n।'))
add(c,'critical-angle',lambda n:Q(f'Medium refractive index {n}/2 (>1), air index1। critical angle sinC কত?',F(2,n),[F(n,2),F(1,n),F(4,n*n)],'At critical angle refracted90°: μsinC=1⇒sinC=1/μ=2/n। light must originate dense medium।'))
add(c,'prism-min-deviation',lambda n:Q(f'Prism angle A=60°, minimum deviation δ=60°। index কত?','√3',['√2','3/2','2'],'μ=sin((A+δ)/2)/sin(A/2)=sin60°/sin30°=√3। minimum deviation symmetric path জরুরি।'))
add(c,'mirror-concave',lambda n:Q(f'Concave mirror f={n}cm। object 2f-এ। image position কোথায়?',f'2f={2*n}cm',[f'f={n}cm','infinity','mirror-এর পিছনে'],'Mirror formula 1/f=1/u+1/v, u=2f⇒v=2f। real inverted same-size image at centre of curvature।'))
add(c,'lens-cut-aperture',lambda n:Q(f'Converging lens focal length {n}cm-এর lower half opaque করলে image কীভাবে বদলায়?','পূর্ণ image, brightness কমে',['অর্ধেক image','focal length doubles','image vanish'],'প্রতিটি object point থেকে lens-এর প্রতিটি অংশ ray সংগ্রহ করে। aperture কমালে intensity কমে, full image shape থাকে।'))
add(c,'magnifier-near-point',lambda n:Q(f'Simple magnifier f=25/{n}cm, eye near-point25cm। final image at near-point হলে angular magnification কত?',n+1,[n,n-1,25*n],'Near-point magnification M=1+D/f=1+25/(25/n)=n+1; infinity-image case M=D/f।'))
add(c,'telescope-length',lambda n:Q(f'Astronomical telescope fo={10*n}cm, fe={n}cm normal adjustment। length কত cm?',11*n,[9*n,10,n*n],'Normal adjustment-এ objective real image eyepiece focal plane-এ। tube length fo+fe=11n; magnification10 আলাদা।'))

c='physics-2-07'
add(c,'young-water',lambda n:Q(f'Young double slit air fringe width {n}mm। apparatus water μ=4/3-এ submerged। new width কত mm?',F(3*n,4),[F(4*n,3),n,F(9*n,16)],'Fringe width β=λD/d; medium wavelength λ/μ। entire setup unchanged geometry-এ β′=β/μ=3n/4।'))
add(c,'slit-path-dark',lambda n:Q(f'Young experiment wavelength {n}nm। path difference 3λ/2। fringe type কী?','অন্ধকার',['কেন্দ্রীয় উজ্জ্বল','দ্বিতীয় উজ্জ্বল','সমান intermediate'],'Destructive interference Δ=(m+½)λ। 3λ/2 corresponds m=1, dark fringe; integer wavelengths bright।'))
add(c,'malus-two-polarisers',lambda n:Q(f'Initially unpolarised intensity {2*n}W/m²। ideal polariser পরে analyser at60°। final intensity কত?',F(n,4),[F(n,2),n,F(3*n,4)],'প্রথম polariser unpolarised intensity অর্ধেক করে n। Malus at60° gives n cos²60°=n/4।'))
add(c,'brewster',lambda n:Q(f'Air→medium refractive index {n}/2। Brewster angle tanθB কত?',F(n,2),[F(2,n),F(n*n,4),F(1,n)],'Brewster law tanθB=n₂/n₁। incident medium air1 হলে tanθB=n/2; critical angle sine law আলাদা।'))
