add(c,'grating-order-limit',lambda n:Q(f'Grating slit spacing {n}λ। maximum allowed diffraction order কত?',n,[n-1,2*n,F(n,2)],'d sinθ=mλ এবং |sinθ|≤1⇒|m|≤d/λ=n। grazing-order m=n geometrically allowed (θ=90°)।'))
add(c,'coherent-intensity',lambda n:Q(f'Two coherent sources individual intensities I ও4I, I={n}। Imax/Imin কত?',9,[5,4,F(9,5)],'Amplitudes proportional√I: A,2A। max intensity9I, minI। ratio9; intensities সরাসরি add নয়।'))
add(c,'phase-intensity',lambda n:Q(f'Two equal coherent sources each intensity {n}। phase difference90°। resultant intensity কত?',2*n,[4*n,0,n],'I=I₁+I₂+2√(I₁I₂)cosφ। cos90°=0⇒2n; equal amplitudes হলেও constructive নয়।'))
