add(c,'photoelectric-frequency',lambda n:Q(f'Photon energy {n+3}eV, work function3eV। stopping potential কত V?',n,[n+3,3,F(n,2)],'Einstein Kmax=hf−φ=(n+3)−3=n eV। electron charge conversionে stopping voltage nV।'))
