add(c,'length-contraction',lambda n:Q(f'Proper rod length {5*n}m। moves parallel at0.6c। measured length কত m?',4*n,[F(25*n,4),5*n,3*n],'Length contraction L=L₀√(1−v²/c²)=5n·0.8=4n। transverse direction would unchanged।'))
