c='physics-2-09'
add(c,'half-life-fraction',lambda n:Q(f'Half-life {n}days। 3 half-lives পরে original nuclei fraction কত?',F(1,8),[F(3,8),F(1,3),F(7,8)],'Radioactive N=N₀(½)^(t/T½)। t=3T½⇒remaining1/8; decayed fraction7/8।'))
