add(c,'alpha-beta-chain',lambda n:Q(f'Nucleus (A,Z)=({200+n},80) emits one α then two β⁻। final (A,Z) কোনটি?',f'({196+n},80)',[f'({196+n},76)',f'({200+n},82)',f'({196+n},78)'],'Alpha changes A−4,Z−2; each beta− leaves A and raises Z by1। two restore Z80, final A196+n।'))
