add(c,'bohr-radius',lambda n:Q(f'Hydrogen-like ion Z={n}, principal level2। radius/a₀ কত?',F(4,n),[F(2,n),4*n,F(n,4)],'Bohr r=a₀ nlevel²/Z। level2⇒4a₀/Z; nucleus charge কমায়;  radius, level square expands।'))
add(c,'binding-per-nucleon',lambda n:Q(f'Nucleus mass number {4*n}, total binding energy {32*n}MeV। binding per nucleon কত MeV?',8,[32,4,n],'Average binding=B/A=(32n)/(4n)=8MeV per nucleon। total energy ও average আলাদা।'))
add(c,'mass-defect',lambda n:Q(f'Mass defect {n}/1000u, 1u c²=931.5MeV। binding energy কত MeV?',F(1863*n,2000),[F(1863*n,200),931.5*n,F(n,931500)],'Binding Δmc²=(n/1000)·931.5=0.9315nMeV। factor1000 from mass units রাখতে হয়।'))
