add(c,'photon-transition-count',lambda n:Q(f'Atomic electrons excited to level {n}। সকল downward transitions possible। maximum distinct line count কত?',F(n*(n-1),2),[n-1,n*n,2*n],'Any pair of levels gives one transition in simple nondegenerate model। total pairs C(n,2)=n(n−1)/2।'))
add(c,'decay-log-inference',lambda n:Q(f'Activity A→A/4 সময় {2*n}s-এ। half-life কত s?',n,[2*n,F(n,2),4*n],'A/4=(½)²A মানে 2 half-lives elapsed। T½=(2n)/2=n s।'))

