add(c,'diode-series-circuit',lambda n:Q(f'Supply {n+1}V, forward Si diode drop0.7V ও Ge drop0.3V series with1kΩ। current কত mA?',n,[n+1,F(n,1000),0],'Assume both forward conducting at stated constant drops। resistor voltage V−(0.7+0.3)=nV। I=n/1000A=n mA।'))
