add(c,'transistor-current',lambda n:Q(f'Transistor β=50, base current {n}μA। emitter current কত μA?',51*n,[50*n,49*n,n],'Collector Ic=βIb=50nμA। emitter Ie=Ic+Ib=51nμA, collector আর emitter সমান নয়।'))
add(c,'logic-nand',lambda n:Q(f'A=1,B={n%2}। NAND output কত?',1-n%2,[n%2,'অনির্দিষ্ট','A+B'],'NAND=NOT(A AND B)। A=1-এ AND=B, invert করলে output1−B। logic truth table সরাসরি।'))
add(c,'logic-de-morgan',lambda n:Q(f'Boolean Y=NOT(A+B), A={n%2}। কোন equivalent form সঠিক?','(NOT A)·(NOT B)',['(NOT A)+(NOT B)','A·B','A+B'],'De Morgan: OR-এর complement=individual complement-এর AND। inversion gate/operation দুটো পরিবর্তন করে।'))
add(c,'rectifier-frequency',lambda n:Q(f'AC mains frequency {n}Hz। ideal full-wave rectified ripple fundamental frequency কত?',2*n,[n,F(n,2),4*n],'Full wave-এ positive ও negative half-cycle দুটোই same polarity। period T/2; ripple frequency2f।'))
add(c,'bridge-diode-drop',lambda n:Q(f'Bridge rectifier input peak {n+2}V, conducting silicon diodes0.7V each। load peak voltage কত V?',F(5*n+3,5),[F(10*n+13,10),n+2,n],'Bridge conduction path-এ two diode drops1.4V। Vloadpeak=n+2−1.4=n+0.6V; one diode নয়।'))
add(c,'zener-regulator',lambda n:Q(f'Zener 5V regulator, input {n+5}V, series resistor1kΩ; no load। zener current কত mA?',n,[n+5,5,F(n,1000)],'Breakdown operation assumed। resistor drop Vin−Vz=nV। no load-এ সব current zener-এ=n mA।'))
add(c,'binary-adder',lambda n:Q(f'Binary 1011₂ + {"0011" if n%2 else "0101"}₂-এর decimal value কত?',14 if n%2 else 16,[11,3 if n%2 else 5,15],'1011₂=11। দ্বিতীয় সংখ্যা3 বা5; decimal sum14 বা16। binary carry বাদ দিলে ভুল।'))
add(c,'xor-parity',lambda n:Q(f'A={n%2}, B=1। XOR output কত?',1-n%2,[n%2,'A+B','অনির্দিষ্ট'],'XOR1 যখন inputs ভিন্ন। B=1-এ A=0 দিলে1, A=1 দিলে0; তাই output1−A।'))

c='physics-2-11'
add(c,'parallax-distance',lambda n:Q(f'এক star parallax1/{n} arcsecond। distance কত parsec?',n,[F(1,n),n*n,206265*n],'Parsec definition d(pc)=1/p(arcsec)। p=1/n⇒d=n pc; arcsecond degree নয়।'))
add(c,'luminosity-flux',lambda n:Q(f'Same star distance d→{n}d। observed flux ratio new/old কত?',F(1,n*n),[F(1,n),n*n,1],'Inverse-square flux F=L/(4πd²)। luminosity unchanged, distance factor n gives flux1/n²।'))
add(c,'stellar-radius-temperature',lambda n:Q(f'Star radius R→{n}R ও temperature T→2T। luminosity factor কত?',16*n*n,[4*n*n,16*n,2*n*n],'L=4πR²σT⁴। radius contributes n², temperature16; factor16n²।'))
add(c,'hubble-distance',lambda n:Q(f'H₀=70km/s/Mpc, galaxy distance {n}Mpc; local linear approximation। recession speed কত km/s?',70*n,[F(n,70),70+n,700*n],'Hubble law v≈H₀d for low redshift; multiply70×n with Mpc cancel to km/s।'))
add(c,'redshift-wavelength',lambda n:Q(f'Emission rest wavelength500nm, observed{500+10*n}nm। redshift z কত?',F(n,50),[F(50,n),F(n,500),F(10*n,500+10*n)],'z=(λobs−λrest)/λrest=10n/500=n/50। denominator rest wavelength, observed নয়।'))
add(c,'light-travel-time',lambda n:Q(f'Star distance {n}light-year। received photons কত বছর আগে emitted? relative motion উপেক্ষা',n,[F(n,3),3*n,n*n],'এক light-year আলো এক বছরে যায়। distance n light-year-এ light travel time n বছর; distance unit time conversion।'))
add(c,'escape-black-hole',lambda n:Q(f'Black hole Schwarzschild radius Rs=2GM/c²। mass {n} গুণ হলে Rs factor কত?',n,[n*n,F(1,n),1],'Schwarzschild radius mass-এর linear function at fixed G,c। factor n mass gives factor n radius।'))
add(c,'angular-size',lambda n:Q(f'Small-angle object sizeD, distance d-এ θ। same size distance {n}d-এ angular size কত?',f'θ/{n}',[f'{n}θ',f'θ/{n*n}','θ'],'Small-angle θ≈D/d radians। same physical size-এ angular size distance inverse first power।'))
add(c,'kepler-star-mass',lambda n:Q(f'Two circular planets same orbital radius but central star mass M ও{n}M। period ratio second/first কত?',f'1/√{n}',[f'√{n}',f'1/{n}',str(n)],'Newton–Kepler T=2π√(r³/(GM))। same r-এ T∝M⁻½, তাই ratio1/√n।'))
add(c,'magnitude-flux',lambda n:Q(f'Star A apparent magnitude {n}, B magnitude {n+5}। flux FA/FB কত?',100,[5,10,F(1,100)],'Pogson relation magnitude difference5 corresponds flux ratio100। Smaller magnitude brighter⇒A has100×B flux।'))
